fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Ensure inputs have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    
    // Consume both vectors, zip their items, XOR them, and collect into a new Vec<u8>
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x ^ y)
     .collect()
}

