    #[test]
    fn test_bitwise_xor_basic() {
        let a = vec![0b0000_0000, 0b1111_0000, 0b1010_1010];
        let b = vec![0b0000_0000, 0b0000_1111, 0b0101_0101];
        let result = bitwise_xor(a, b);
        assert_eq!(result, vec![0b0000_0000, 0b1111_1111, 0b1111_1111]);
    }

    #[test]
    fn test_bitwise_xor_all_ones() {
        let a = vec![0xFF; 5];
        let b = vec![0xFF; 5];
        let result = bitwise_xor(a, b);
        // 0xFF ^ 0xFF == 0x00
        assert_eq!(result, vec![0x00; 5]);
    }

